<?php $title='Shop'; require 'includes/header.php'; $cats=$pdo?$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll():[]; $where='1=1';$args=[];if(!empty($_GET['category'])){$where='p.category_id=?';$args[]=(int)$_GET['category'];}$list=products($pdo,0,$where,$args); ?>
<div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><p class="eyebrow mb-1">Everything you need</p><h1 class="section-title mb-0">Shop all products</h1></div><div class="input-group" style="max-width:360px"><span class="input-group-text bg-white"><i class="fa fa-search"></i></span><input id="liveSearch" class="form-control" placeholder="Search name or category..."></div></div><div class="d-flex gap-2 flex-wrap mb-4"><a class="btn btn-sm rounded-pill <?=empty($_GET['category'])?'btn-primary':'btn-outline-primary'?>" href="<?=url('products.php')?>">All</a><?php foreach($cats as $c): ?><a class="btn btn-sm rounded-pill <?=($_GET['category']??'')==$c['id']?'btn-primary':'btn-outline-primary'?>" href="<?=url('products.php?category='.$c['id'])?>"><?=e($c['name'])?></a><?php endforeach; ?></div><div class="row g-4"><?php foreach($list as $p) include 'includes/product-card.php'; if(!$list): ?><p class="text-muted">Database unavailable or no products found. Import database/database.sql.</p><?php endif; ?></div><?php require 'includes/footer.php'; ?>
